module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Reset the flip-flops to zero (initial values)
    initial begin
        q0 = 1'b0;
        q1 = 1'b0;
        q2 = 1'b0;
    end

    // D flip-flops triggered on the positive edge of the clock
    always @(posedge clk) begin
        q0 <= q0 ^ x;          // XOR gate: second input is q0 itself
        q1 <= q1 & x;          // AND gate: second input is ~q1 (complemented)
        q2 <= q2 | x;          // OR gate: second input is ~q2 (complemented)
    end

    // Three-input NOR gate: NOR(q0, q1, q2)
    // In SystemVerilog, ~(|{a,b,c}) implements a NOR gate.
    assign z = ~(q0 | q1 | q2);

endmodule

