module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    // State encoding: 3 bits as specified
    logic [2:0] y;

    // Next-state logic (combinational)
    always_comb begin
        case (y)
            3'b000: begin
                if (x == 1'b0)
                    y = 3'b000;
                else
                    y = 3'b001;
            end
            3'b001: begin
                if (x == 1'b0)
                    y = 3'b001;
                else
                    y = 3'b100;
            end
            3'b010: begin
                if (x == 1'b0)
                    y = 3'b010;
                else
                    y = 3'b001;
            end
            3'b011: begin
                if (x == 1'b0)
                    y = 3'b001;
                else
                    y = 3'b010;
            end
            3'b100: begin
                if (x == 1'b0)
                    y = 3'b011;
                else
                    y = 3'b100;
            end
            default: y = 3'b000; // Should never happen
        endcase
    end

    // Output logic (combinational)
    always_comb begin
        case (y)
            3'b000: z = 1'b0;
            3'b001: z = 1'b0;
            3'b010: z = 1'b0;
            3'b011: z = 1'b1;
            3'b100: z = 1'b1;
            default:  z = 1'b0;
        endcase
    end

    // Sequential logic (positive-edge triggered flip-flops)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y; // Will be updated with next-state value
    end

    // Register update: capture next-state on clock edge
    // Note: The 'y' variable above is the current state.
    // We need a separate register for the next state to avoid
    // feedback issues in simulation synthesis. However, the
    // standard pattern for simple FSMs is to use non-blocking
    // assignments in the always_ff block driven by the
    // combinational always_comb block.
    // To make this fully synthesizable and match the table,
    // we assign the next state directly.

    // Re-structure: The always_ff block updates 'y' based on
    // the next-state mux. Since we used 'y' in always_comb,
    // we must be careful. The typical pattern is:
    logic [2:0] next_y;

    always_comb begin
        case (y)
            3'b000: next_y = (x == 1'b0) ? 3'b000 : 3'b001;
            3'b001: next_y = (x == 1'b0) ? 3'b001 : 3'b100;
            3'b010: next_y = (x == 1'b0) ? 3'b010 : 3'b001;
            3'b011: next_y = (x == 1'b0) ? 3'b001 : 3'b010;
            3'b100: next_y = (x == 1'b0) ? 3'b011 : 3'b100;
            default:  next_y = 3'b000;
        endcase
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= next_y;
    end

    // Output assignment
    always_comb begin
        case (y)
            3'b011, 3'b100: z = 1'b1;
            default:        z = 1'b0;
        endcase
    end

endmodule

