module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT   = 4'b0001,
        WALK_RIGHT  = 4'b0010,
        FALLING     = 4'b0100,
        DIGGING     = 4'b1000,
        SPLATTERED  = 4'b0000
    } state_t;

    // State registers with reset value
    state_t state, next_state;

    // Output logic (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // Next-state logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            // Default: stay in current state
            state <= next_state;
        end
    end

    // Combinational next-state logic
    always_comb begin
        // Default next state is current state
        next_state = state;

        // Priority: fall > dig > switch directions
        // 1. Fall has highest precedence
        if (ground == 0) begin
            // If falling and has been falling for more than 20 cycles -> splatter
            if (state == FALLING && /* falling counter */ 1'b0) begin
                // TODO: implement falling counter for splatter detection
                // For now, just stay falling
            end else begin
                next_state = FALLING;
            end
        end else begin
            // ground == 1
            if (state == FALLING) begin
                // Ground reappeared - resume walking in original direction
                // (logic would depend on previous direction before fall)
                next_state = WALK_LEFT; // Placeholder
            end else if (state == DIGGING) begin
                // Digging reached other side (ground=0) -> fall
                // But ground=1 here, so this case shouldn't happen in same cycle
                // Actually: dig continues until ground=0, then fall
                // Since ground=1, stay digging or resume walking?
                // Specification: "will continue digging until it reaches the other side (ground=0)"
                // So if ground=1 and digging, keep digging
                next_state = DIGGING;
            end else begin
                // Walking state - check conditions
                // Priority: fall > dig > switch directions

                // Check fall: ground=0 would cause fall, but we're in ground=1 block
                // Actually fall happens when ground goes from 1 to 0
                // For now, assume level changes happen between cycles

                // Check dig: can dig if ground=1 and not falling
                if (dig == 1'b1) begin
                    next_state = DIGGING;
                end else begin
                    // Check direction switch
                    if (bump_left == 1'b1 || bump_right == 1'b1) begin
                        // If bumped on left -> walk right
                        // If bumped on right -> walk left
                        // If bumped on both -> still switch directions
                        if (bump_left == 1'b1) begin
                            next_state = WALK_RIGHT;
                        end else if (bump_right == 1'b1) begin
                            next_state = WALK_LEFT;
                        end else begin
                            // Both bumped - switch directions
                            // If currently walking left, go right, and vice versa
                            // Need to know current direction
                            if (state == WALK_LEFT) begin
                                next_state = WALK_RIGHT;
                            end else begin
                                next_state = WALK_LEFT;
                            end
                        end
                    end
                    // else stay in current walking state
                end
            end
        end
    end

endmodule

