module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot encoded next-state signals
    reg [9:0] next_state;

    // Combinational next-state logic (derived by inspection of the state diagram)
    always @(*) begin
        case (state)
            10'b0000000001: // S
                next_state = d ? 10'b0000000010 : 10'b0000000001; // d=1 -> S1, else S
            10'b0000000010: // S1
                next_state = d ? 10'b0000000100 : 10'b0000000001; // d=1 -> S11, else S
            10'b0000000100: // S11
                next_state = d ? 10'b0000001000 : 10'b0000000100; // d=1 -> S11, else S110
            10'b0000001000: // S110
                next_state = d ? 10'b1000000000 : 10'b0000000001; // d=1 -> B0, else S
            10'b1000000000: // B0
                next_state = 10'b0100000000; // always -> B1
            10'b0100000000: // B1
                next_state = 10'b0010000000; // always -> B2
            10'b0010000000: // B2
                next_state = 10'b0001000000; // always -> B3
            10'b0001000000: // B3
                next_state = 10'b0000100000; // always -> Count
            10'b0000100000: // Count
                next_state = done_counting ? 10'b0000010000 : 10'b0000100000; // done_counting=1 -> Wait, else Count
            10'b0000010000: // Wait
                next_state = ack ? 10'b0000000001 : 10'b0000010000; // ack=1 -> S, else Wait
            default: next_state = 10'b0000000001; // reset fallback
        endcase
    end

    // One-hot decoded next-state asserts
    assign S_next   = (next_state == 10'b0000000001);
    assign S1_next  = (next_state == 10'b0000000010);
    assign B3_next  = (next_state == 10'b0001000000);
    assign Count_next = (next_state == 10'b0000100000);
    assign Wait_next = (next_state == 10'b0000010000);

    // Output logic (Moore machine: outputs depend only on current state)
    // shift_ena: asserted in B0, B1, B2, B3
    assign shift_ena = (state == 10'b1000000000) | 
                       (state == 10'b0100000000) | 
                       (state == 10'b0010000000) | 
                       (state == 10'b0001000000);

    // counting: asserted in Count state
    assign counting = (state == 10'b0000100000);

    // done: asserted in Wait state
    assign done = (state == 10'b0000010000);

endmodule

