module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum reg [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    reg [1:0] state, next_state;
    reg [7:0] byte_reg;   // Holds the current byte being shifted in
    reg [2:0] byte_cnt;   // Counter: 1, 2, or 3

    // FSM state transition logic (sequential always block)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            byte_cnt  <= 0;
            byte_reg  <= 8'h00;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0;   // Default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        byte_cnt   <= 1;
                        byte_reg   <= in;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    if (!in[3]) begin  // Continue receiving while in[3]=0
                        next_state <= BYTE2;
                        byte_cnt   <= 2;
                        byte_reg   <= in;
                    end
                    // If in[3]=1 again, treat as new message start (stay in BYTE1)
                end

                BYTE2: begin
                    // Receive third byte
                    if (!in[3]) begin
                        next_state <= BYTE3;
                        byte_cnt   <= 3;
                        byte_reg   <= in;
                    end
                end

                BYTE3: begin
                    // Third byte received – assert done next cycle
                    next_state <= IDLE;
                    done       <= 1'b1;
                    // Shift the three bytes into out_bytes (byte1 first MSB)
                    out_bytes <= {byte_reg, byte_reg, byte_reg}; 
                    // Actually we need to keep the three bytes separately.
                    // We'll use a separate register file or just compute out_bytes
                    // from the three captured bytes. Since we only have one byte_reg,
                    // we need to remember the previous two bytes.
                    // To keep it simple with minimal logic, we capture the three
                    // bytes into three registers.
                end
            endcase
        end
    end

    // Additional registers to hold the three bytes of the current message
    reg [7:0] byte1, byte2, byte3;

    // Update the byte registers on every clock (simplified: we overwrite
    // them as we progress through the FSM). For clarity, we'll update
    // them in the sequential block below.

    // Re-assign byte registers based on state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            byte1 <= 8'h00;
            byte2 <= 8'h00;
            byte3 <= 8'h00;
        end else begin
            case (state)
                IDLE: begin
                    if (in[3]) begin
                        byte1 <= in;
                    end
                end
                BYTE1: begin
                    byte2 <= in;
                end
                BYTE2: begin
                    byte3 <= in;
                end
                BYTE3: begin
                    // bytes already latched; keep them for out_bytes output
                end
            endcase
        end
    end

    // Output assignment: out_bytes valid when done is asserted
    // out_bytes[23:16] = byte1, [15:8] = byte2, [7:0] = byte3
    always @* begin
        if (done) begin
            out_bytes = {byte1, byte2, byte3};
        end else begin
            out_bytes = 24'h00;  // Don't-care, but drive 0
        end
    end

    // FSM next-state combinational logic
    always @* begin
        next_state = IDLE;
        case (state)
            IDLE: begin
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = IDLE;
            end
            BYTE1: begin
                // If the next byte also has in[3]=1, we treat it as a new message start
                // (i.e., stay in BYTE1 and update byte1). Otherwise go to BYTE2.
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = BYTE2;
            end
            BYTE2: begin
                if (in[3])
                    next_state = BYTE1;  // New message start
                else
                    next_state = BYTE3;
            end
            BYTE3: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule

