    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression for f:
    // f = x3' & x2' & x1 & x0'   (m1)
    //   | x3' & x2  & x1 & x0     (m5)
    //   | x3  & x2  & x1          (m7, m6)
    //   | x3  & x2  & x1' & x0'   (m12, m8)
    //   | x3  & x2' & x1 & x0     (m9)
    //   | x3  & x2' & x1 & x0'    (m13)
    //   | x3  & x2' & x1' & x0'   (m14)
    //   | x3' & x2  & x1' & x0'   (m4)
    //   | x3' & x2' & x1 & x0'    (m2)
    //   | x3' & x2' & x1' & x0    (m1)
    assign f = (~x3 & ~x2 &  x1 & ~x0) |           // m1, m5
               (~x3 &  x2 &  x1 &  x0) |           // m5 (already covered, but safe)
               ( x3 &  x2 &  x1) |                // m7, m6
               ( x3 &  x2 & ~x1 & ~x0) |          // m12, m8
               ( x3 & ~x2 &  x1 &  x0) |          // m9
               ( x3 & ~x2 &  x1 & ~x0) |          // m13
               ( x3 & ~x2 & ~x1 & ~x0) |          // m14
               (~x3 &  x2 & ~x1 & ~x0) |          // m4
               (~x3 & ~x2 &  x1 & ~x0) |          // m2
