module TopModule (
    input  clk,
    input  reset,
    output ena    // 3 bits: enable for tens, hundreds, thousands
    output q      // 16 bits: BCD digits
);

    // Internal registers for the 4 BCD digits (ones, tens, hundreds, thousands)
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // ena outputs: enable for the next higher digit
    // ena[0] -> tens enable, ena[1] -> hundreds enable, ena[2] -> thousands enable
    assign ena = {tens[3], hundreds[3], thousands[3]};

    // BCD counter logic
    always @(posedge clk) begin
        if (reset) begin
            ones    <= 4'd0;
            tens    <= 4'd0;
            hundreds <= 4'd0;
            thousands <= 4'd0;
        end else begin
            // Ones digit: increments every cycle, rolls over at 9 (1010)
            if (ones == 4'd9)
                ones <= 4'd0;
            else
                ones <= ones + 1'b1;

            // Tens digit: increments when ones rolls over from 9
            if (ones == 4'd9)
                if (tens == 4'd9)
                    tens <= 4'd0;
                else
                    tens <= tens + 1'b1;

            // Hundreds digit: increments when tens rolls over from 9
            if (ones == 4'd9 && tens == 4'd9)
                if (hundreds == 4'd9)
                    hundreds <= 4'd0;
                else
                    hundreds <= hundreds + 1'b1;

            // Thousands digit: increments when hundreds rolls over from 9
            if (ones == 4'd9 && tens == 4'd9 && hundreds == 4'd9)
                if (thousands == 4'd9)
                    thousands <= 4'd0;
                else
                    thousands <= thousands + 1'b1;
        end
    end

    // Concatenate the 4 digits to form the 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

endmodule

