module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // FSM state encoding (2 bits)
    typedef enum logic [1:0] {
        STATE_A   = 2'b00,
        STATE_B   = 2'b01,
        STATE_C   = 2'b10,
        STATE_D   = 2'b11
    } state_t;

    // State register with synchronous active-low reset
    state_t state, next_state;

    // Outputs (registered to avoid combinational loops)
    logic f_reg, g_reg;

    // ---------------------------------------------------------------
    // Next-state logic (combinational)
    // ---------------------------------------------------------------
    always_comb begin
        // Default assignments: stay in current state unless transition conditions met
        next_state = state;

        case (state)
            STATE_A: begin
                // As long as resetn is asserted (low), stay in STATE_A
                if (!resetn) next_state = STATE_A;
                // When reset is de-asserted, go to STATE_B at next clock edge
                else        next_state = STATE_B;
            end

            STATE_B: begin
                // After reset de-assertion, set f = 1 for one clock cycle
                // Transition to STATE_C regardless of x/y
                next_state = STATE_C;
            end

            STATE_C: begin
                // Monitor x for the sequence 1, 0, 1 over three successive cycles
                // If the sequence is detected, go to STATE_D
                // Otherwise stay in STATE_C
                if (!resetn) begin
                    next_state = STATE_A;
                end else if (x == 1'b1) begin
                    // First '1' of the sequence seen; advance to check for 0,1
                    next_state = STATE_D;
                end else begin
                    // x not 1, reset sequence detection
                    next_state = STATE_C;
                end
            end

            // STATE_D is a helper state meaning "we have seen a 1, waiting for 0 then 1"
            STATE_D: begin
                if (!resetn) begin
                    next_state = STATE_A;
                end else begin
                    // Check if the next x is 0 then 1 to complete the sequence
                    // Since we only look at the current x, we transition based on
                    // the pattern: if x is 0, go to a "saw 0" state; if 1, complete.
                    // To keep within the 2-bit state encoding, we repurpose STATE_A
                    // after seeing a 0, and use STATE_D to detect the final 1.
                    // However, the specification requires detecting 1,0,1 over
                    // three cycles. We will use the current x and the fact that
                    // we just came from STATE_C with x=1.
                    // Simplified: if x is 0, we move to a pending state; if 1, success.
                    // Given the 2-bit limit, we encode "saw 0" as STATE_A and
                    // detect the final 1 in the next cycle.
                    if (x == 1'b0) begin
                        // Saw the 0, now waiting for the final 1
                        next_state = STATE_A; // reuse STATE_A as "saw 0 waiting for 1"
                    end else begin
                        // x is 1 -> we have seen 1 (from STATE_C), 0 (just now), 1 (now) -> complete
                        next_state = STATE_B; // transition to STATE_B to trigger f pulse
                    end
                end
            end

            default: begin
                if (!resetn) begin
                    next_state = STATE_A;
                end else begin
                    next_state = STATE_A;
                end
            end
        endcase
    end

    // ---------------------------------------------------------------
    // Sequence tracking and output logic
    // ---------------------------------------------------------------
    always_ff @(posedge clk) begin
        if (!resetn) begin
            state          <= STATE_A;
            f_reg          <= 1'b0;
            g_reg          <= 1'b0;
        end else begin
            // Update state
            state <= next_state;

            // Output f: pulse high for one cycle when entering STATE_B from STATE_A
            if (state == STATE_B) begin
                f_reg <= 1'b1;
            end else begin
                f_reg <= 1'b0;
            end

            // g logic: set to 1 when the sequence 1,0,1 is detected
            // and y becomes 1 within 2 clock cycles while g is high.
            // We detect the complete 1,0,1 sequence by transitioning
            // through STATE_D. When we enter STATE_B from the sequence
            // detection, we set g_reg to 1.
            if (next_state == STATE_B && state == STATE_D) begin
                // We have just detected the 1,0,1 sequence.
                // Now we need to monitor y while g is high.
                // For simplicity, we set g_reg here and use a counter
                // to clear it if y does not come high within 2 cycles.
                g_reg <= 1'b1;
            end else if (state == STATE_B && f_reg == 1'b0) begin
                // If we are in STATE_B but not just entered (f_reg already high),
                // we still need to handle the y monitoring.
                // The specification says: "While maintaining g = 1 the FSM has
                // to monitor the y input." This implies g stays 1 as long
                // as reset is active and the condition holds.
                // We will implement the counter and y check here.
                if (y == 1'b1) begin
                    g_reg <= 1'b1;
                end else begin
                    // y is 0; we need to track cycles.
                    // Since we don't have a counter register in this snippet,
                    // we infer: if y stays 0 for two cycles, g should clear.
                    // To properly implement, a counter is needed. We'll add
                    // a simple counter below.
                end
            end

            // Counter to track cycles without y=1 while g is high
            // We use a 2-bit counter: 00 (0 cycles), 01 (1 cycle), 10 (2 cycles).
            // If we reach 2 cycles without y=1, we set g=0 permanently.
            // Note: The counter logic is integrated with the g_reg update.
            // For this fix, we will track the counter in a separate always block
            // and combine with g_reg.
        end
    end

    // ---------------------------------------------------------------
    // Counter and refined g logic
    // ---------------------------------------------------------------
    logic [1:0] y_wait_counter; // 2-bit counter: 00, 01, 10

    always_ff @(posedge clk) begin
        if (!resetn) begin
            state          <= STATE_A;
            f_reg          <= 1'b0;
            g_reg          <= 1'b0;
            y_wait_counter <= 2'b00;
        end else begin
            // Update state
            state <= next_state;

            // Output f: pulse high for one cycle when entering STATE_B from STATE_A
            if (state == STATE_B) begin
                f_reg <= 1'b1;
            end else begin
                f_reg <= 1'b0;
            end

            // g logic with counter
            if (g_reg == 1'b1) begin
                // g is currently high; monitor y
                if (y == 1'b1) begin
                    // y became 1, reset counter and keep g=1
                    y_wait_counter <= 2'b00;
                end else begin
                    // y still 0, increment counter
                    if (y_wait_counter == 2'b10) begin
                        // Have waited 2 cycles without y=1 -> set g=0 permanently
                        g_reg <= 1'b0;
                        y_wait_counter <= 2'b11; // mark as expired
                    end else begin
                        y_wait_counter <= y_wait_counter + 1'b1;
                    end
                end
            end else begin
                // g is 0; if we detect the 1,0,1 sequence, set g=1
                if (next_state == STATE_B && state == STATE_D) begin
                    g_reg <= 1'b1;
                    y_wait_counter <= 2'b00;
                end else begin
                    g_reg <= 1'b0;
                    y_wait_counter <= 2'b00;
                end
            end

            // Update state (already done above, but keeping structure clear)
            // Note: state assignment is done at the top of the else block.
        end
    end

    // ---------------------------------------------------------------
    // Final output assignments
    // ---------------------------------------------------------------
    assign f = f_reg;
    assign g = g_reg;

endmodule

