module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    // State encoding: 0=idle, 1=first_1, 2=second_1, 3=0, 4=1_found
    typedef enum logic [2:0] {
        IDLE   = 3'b000,
        FIRST  = 3'b001,
        SECOND = 3'b010,
        ZERO   = 3'b011,
        ONE    = 3'b100
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            IDLE:     next_state = (data == 1'b1) ? FIRST : IDLE;
            FIRST:    next_state = (data == 1'b1) ? SECOND : IDLE;
            SECOND:   next_state = (data == 1'b0) ? ZERO  : SECOND;
            ZERO:     next_state = (data == 1'b1) ? ONE   : IDLE;
            ONE:      next_state = IDLE;           // sequence 1101 completed
            default:  next_state = IDLE;
        endcase
    end

    // Output logic: assert start_shifting when we are in the state after detecting '1' (the 4th bit)
    assign start_shifting = (state == ONE);

    // Flip-flops with synchronous reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Optional: initialize register to avoid latch inference if synthesis tools complain
    // (Icarus Verilog -g2012 handles this, but good practice)
    initial begin
        state = IDLE;
    end

endmodule

