module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal signals for flow control
    wire [2:0] nominal;
    wire level_low, level_mid, level_high;

    // Assign nominal flow rates based on current water level sensors
    // Above s[2]: None (000)
    // Between s[2] and s[1]: fr0 (001)
    // Between s[1] and s[0]: fr0, fr1 (011)
    // Below s[0]: fr0, fr1, fr2 (111)
    assign nominal = (s == 3'b111) ? 3'b000 :
                     (s == 3'b110) ? 3'b001 :
                     (s == 3'b100) ? 3'b011 :
                     3'b111;

    // Level detection
    assign level_high = |s;          // Above highest sensor
    assign level_mid  = (s == 3'b110) || (s == 3'b100); // Between sensors
    assign level_low  = (s == 3'b000); // Below lowest sensor

    // Output assignments based on level and supplemental flow
    // fr0 is always asserted when any flow is requested
    assign fr0 = 1'b1;
    // fr1 from nominal or supplemental
    assign fr1 = nominal[1] | dfr;
    // fr2 from nominal only
    assign fr2 = nominal[2];
    // Supplemental flow control: active when below lowest sensor
    assign dfr = level_low;

    // Synchronous reset logic: resets to state equivalent to long low water level
    // (no sensors asserted, all four outputs asserted)
    always @(posedge clk) begin
        if (reset) begin
            // Reset state: all outputs asserted, dfr forced high
            fr0 <= 1'b1;
            fr1 <= 1'b1;
            fr2 <= 1'b1;
            dfr <= 1'b1;
        end
    end

endmodule
